3| *  Licensed under the MIT License.
4| *--------------------------------------------------------------------------------------------*/
5|
6|import type * as vscode from 'vscode';
7|
8|/**
9| * Map panda engine events to Chat markdown progress.
10| */
11|export class StreamMapper {
12|	private lastStatus = '';
13|	private streamedAssistant = false;
14|
15|	constructor(private readonly stream: vscode.ChatResponseStream) { }
16|
17|	handle(event: string, data: unknown): void {
18|		const d = (data && typeof data === 'object') ? data as Record<string, unknown> : {};
19|
20|		switch (event) {
21|			case 'panda_stream': {
22|				const delta = typeof d.delta === 'string' ? d.delta
23|					: typeof d.text === 'string' ? d.text
24|						: typeof d.content === 'string' ? d.content
25|							: '';
26|				if (delta) {
27|					this.stream.markdown(delta);
28|					this.streamedAssistant = true;
29|				}
30|				break;
31|			}
32|			case 'panda_block': {
33|				const type = typeof d.type === 'string' ? d.type : '';
34|				const content = typeof d.content === 'string' ? d.content : '';
35|				if (!content) {
36|					break;
37|				}
38|				if (type === 'assistant_text') {
39|					if (!this.streamedAssistant) {
40|						this.stream.markdown(content);
41|						this.streamedAssistant = true;
42|					} else {
43|						// Prefer stream deltas; avoid duplicating full blocks when streaming already happened
44|						this.stream.markdown('\n\n' + content);
45|					}
46|				} else if (type === 'tool_call' || type === 'tool') {
47|					const name = typeof d.name === 'string' ? d.name : (typeof d.tool === 'string' ? d.tool : 'tool');
48|					this.stream.markdown(`\n\n- **Tool** \`${name}\`${content ? `: ${truncate(content, 240)}` : ''}\n`);
49|				} else if (type === 'system') {
50|					this.stream.markdown(`\n\n_${escapeMd(truncate(content, 300))}_\n`);
51|				}
52|				break;
53|			}
54|			case 'panda_status': {
55|				const msg = typeof d.message === 'string' ? d.message
56|					: typeof d.status === 'string' ? d.status
57|						: typeof d.text === 'string' ? d.text
58|							: '';
59|				if (msg && msg !== this.lastStatus) {
60|					this.lastStatus = msg;
61|					this.stream.markdown(`\n\n_${escapeMd(truncate(msg, 200))}_\n`);
62|				}
63|				break;
64|			}
65|			case 'panda_tool_start': {
66|				const name = typeof d.name === 'string' ? d.name : 'tool';
67|				this.stream.markdown(`\n\n- Running \`${name}\`…\n`);
68|				break;
69|			}
70|			case 'panda_tool_end': {
71|				const name = typeof d.name === 'string' ? d.name : 'tool';
72|				const ok = d.ok !== false;
73|				this.stream.markdown(`\n- \`${name}\` ${ok ? 'done' : 'failed'}\n`);
74|				break;
75|			}
76|			case 'panda_diag': {
77|				// Quiet: ignore verbose diag unless useful later
78|				break;
79|			}
80|			default:
81|				break;
82|		}
83|	}
84|}
85|
86|function truncate(s: string, n: number): string {
87|	const t = s.replace(/\s+/g, ' ').trim();
88|	return t.length > n ? t.slice(0, n - 1) + '…' : t;
89|}
90|
91|function escapeMd(s: string): string {
92|	return s.replace(/([\\`*_[\]{}()#+-.!])/g, '\\$1');
